-- Tricky True or False: 600 new questions, taking it to 901.
--
-- Two fixed choices, so there is no option length to give the answer away.
-- Split: 305 True to 295 False, so the answer is never the safer guess.

insert into public.quiz_questions (
  id,
  category_id,
  prompt,
  correct_answer,
  wrong_answers,
  explanation,
  language_code,
  grade_level,
  subject,
  display_order,
  is_active
)
select
  'tricky_r2_' || lpad(question.ordinality::text, 4, '0'),
  'tricky_true_false',
  question.item ->> 'p',
  question.item ->> 'a',
  array(select jsonb_array_elements_text(question.item -> 'w')),
  question.item ->> 'e',
  'en',
  null,
  question.item ->> 's',
  (
    select coalesce(max(existing.display_order), 0)
    from public.quiz_questions as existing
    where existing.category_id = 'tricky_true_false'
  ) + question.ordinality::integer,
  true
from jsonb_array_elements($questions$
